WITH base AS (SELECT id, customer_id, account_type, balance, status, CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END AS is_open, COALESCE(status, 'NONE') AS status_filled FROM accounts WHERE status IS NOT NULL) SELECT id, customer_id, status, is_open, status_filled, ROW_NUMBER() OVER w_ordered AS seq_no, SUM(balance) OVER (PARTITION BY account_type ORDER BY balance ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM base WINDOW w_ordered AS (ORDER BY is_open DESC, id ASC);
